from AlgorithmImports import *


class IndependentSlotsStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_closes = RollingWindow[float](2)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_lots = {}

    def OnData(self, data):
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            close = float(data.Bars[self.aapl].Close)
            if self.aapl_closes.Count > 0:
                if close < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.Add(close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self._all_rules_ready():
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and not self.strategy_a_pending:
            if (self.spy_sma_50.Previous.Value >= self.spy_sma_200.Previous.Value and
                    self.spy_sma_50.Current.Value < self.spy_sma_200.Current.Value):
                self._place_order(self.spy, -self.strategy_a_lot, "A")

        if self.strategy_b_lot > 0 and not self.strategy_b_pending:
            if self.aapl_rsi_14.Current.Value > 60:
                self._place_order(self.aapl, -self.strategy_b_lot, "B")

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            if (self.spy_closes[1] <= self.spy_sma_200.Previous.Value and
                    spy_close > self.spy_sma_200.Current.Value):
                quantity = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
                if quantity > 0:
                    self._place_order(self.spy, quantity, "A")

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self._place_order(self.aapl, quantity, "B")

    def _all_rules_ready(self):
        return (
            self.spy_sma_200.IsReady
            and self.spy_sma_200.Samples > 200
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.spy_closes.IsReady
            and self.aapl_closes.IsReady
        )

    def _place_order(self, symbol, quantity, lot_name):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_lots[ticket.OrderId] = lot_name
        if lot_name == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.order_lots:
            return

        lot_name = self.order_lots[order_event.OrderId]

        if order_event.FillQuantity != 0:
            if lot_name == "A":
                self.strategy_a_lot += order_event.FillQuantity
                if self.strategy_a_lot < 0:
                    self.strategy_a_lot = 0
            else:
                self.strategy_b_lot += order_event.FillQuantity
                if self.strategy_b_lot < 0:
                    self.strategy_b_lot = 0

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if lot_name == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False
            del self.order_lots[order_event.OrderId]
